/// SPARSE_DELTA: sparse word-delta: emit records only changed words (index, XOR); apply is no-op-on-empty and total-on-apply; all-or-nothing per cell; apply twice = identity
pub const LAW_SPARSE_DELTA: &str = "SPARSE_DELTA";


// ── st:SparseDelta — sparse word-delta law ────────────────────────────

/// Maximum changed words a SparseDelta records (unibit MAX_DELTA_WORDS,
/// lib.rs:275).
pub const MAX_DELTA_WORDS: usize = 64;

/// Sparse (index, XOR) delta over a word block (unibit UDelta shape).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SparseDelta {
    /// Number of changed words recorded (<= MAX_DELTA_WORDS).
    pub count: usize,
    /// Word indices within the block that changed.
    pub indices: [u32; MAX_DELTA_WORDS],
    /// XOR delta per changed word: before[i] ^ after[i].
    pub words: [u64; MAX_DELTA_WORDS],
}

impl SparseDelta {
    /// Empty delta (count 0): applying it must be a no-op.
    pub fn empty() -> SparseDelta {
        SparseDelta {
            count: 0,
            indices: [0u32; MAX_DELTA_WORDS],
            words: [0u64; MAX_DELTA_WORDS],
        }
    }
}

/// Emit the sparse delta between `before` and `after`: only words that
/// actually changed are recorded (unibit emit_delta lib.rs:390-412).
///
/// # Panics
/// Panics if the slices differ in length or more than MAX_DELTA_WORDS words
/// changed.
#[must_use]
#[allow(clippy::cast_possible_truncation)] // count bounded by MAX_DELTA_WORDS check above
pub fn sparse_delta_emit(before: &[u64], after: &[u64]) -> SparseDelta {
    assert!(before.len() == after.len(), "slice length mismatch");
    let mut d = SparseDelta::empty();
    for (i, (b, a)) in before.iter().zip(after.iter()).enumerate() {
        let xor = b ^ a;
        if xor != 0 {
            assert!(d.count < MAX_DELTA_WORDS, "too many changed words");
            d.indices[d.count] = i as u32;
            d.words[d.count] = xor;
            d.count += 1;
        }
    }
    d
}

/// Honest apply (the court's subject): XOR-applies each recorded change.
/// All-or-nothing per cell — the mask (count) is honored BEFORE any word is
/// touched, so no-op-on-empty and total-on-apply (unibit apply_delta
/// lib.rs:437-441).
pub fn sparse_delta_apply(block: &mut [u64], delta: &SparseDelta) {
    let mut i = 0usize;
    while i < delta.count {
        block[delta.indices[i] as usize] ^= delta.words[i];
        i += 1;
    }
}

/// SABOTAGE TWIN (court non-vacuity witness): mutates the block IN PLACE
/// before checking the mask — every slot is OVERWRITTEN unconditionally
/// (assign instead of masked XOR-apply), so an empty (or short) delta
/// clobbers words the honest apply never touches. The all-or-nothing court
/// below must catch this; the honest apply must pass.
pub fn sabotage_delta_apply(block: &mut [u64], delta: &SparseDelta) {
    let mut i = 0usize;
    while i < MAX_DELTA_WORDS {
        block[delta.indices[i] as usize] = delta.words[i];
        i += 1;
    }
}

// ── st:BitfenwickSum — carry-safe 8-lane Fenwick law ──────────────────

/// Lane count of the fixed-height Fenwick tree (unibit add_8/sum_8).
pub const BITFENWICK_LANES: usize = 8;

/// Fixed-height (8) Fenwick tree with wrapping, lane-local arithmetic.
/// Carries never borrow across lanes: every addition is `wrapping_add`
/// inside one `u32` lane (unibit bitfenwick_add_8 lib.rs:796-817).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bitfenwick8 {
    tree: [u32; BITFENWICK_LANES],
}

impl Bitfenwick8 {
    pub const fn zero() -> Bitfenwick8 {
        Bitfenwick8 { tree: [0u32; BITFENWICK_LANES] }
    }

    pub fn lanes(&self) -> [u32; BITFENWICK_LANES] {
        self.tree
    }

    /// Add `delta` at 1-based position `idx` (1..=8): walks the bounded
    /// update chain with wrapping, lane-local arithmetic.
    pub fn add(&mut self, idx: u32, delta: u32) {
        let mut i = idx as usize;
        while i >= 1 && i <= BITFENWICK_LANES {
            self.tree[i - 1] = self.tree[i - 1].wrapping_add(delta);
            i = i + (i & i.wrapping_neg());
        }
    }

    /// Prefix sum over positions 1..=idx via the bounded probe chain.
    pub fn sum_prefix(&self, idx: u32) -> u32 {
        let mut i = idx as usize;
        let mut acc: u32 = 0;
        while i >= 1 && i <= BITFENWICK_LANES {
            acc = acc.wrapping_add(self.tree[i - 1]);
            i = i & (i - 1);
        }
        acc
    }
}

/// Naive reference model (in-test ground truth): a flat per-position value
/// array with a linear prefix scan — the definitional semantics the Fenwick
/// subject must match, same wrapping arithmetic.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NaivePrefix {
    vals: [u32; BITFENWICK_LANES],
}

impl NaivePrefix {
    pub const fn zero() -> NaivePrefix {
        NaivePrefix { vals: [0u32; BITFENWICK_LANES] }
    }

    pub fn add(&mut self, idx: u32, delta: u32) {
        let i = idx as usize;
        if i >= 1 && i <= BITFENWICK_LANES {
            self.vals[i - 1] = self.vals[i - 1].wrapping_add(delta);
        }
    }

    pub fn sum_prefix(&self, idx: u32) -> u32 {
        let i = idx as usize;
        let mut acc = 0u32;
        if i >= 1 && i <= BITFENWICK_LANES {
            let mut k = 0usize;
            while k < i {
                acc = acc.wrapping_add(self.vals[k]);
                k += 1;
            }
        }
        acc
    }

    pub fn vals(&self) -> [u32; BITFENWICK_LANES] {
        self.vals
    }
}

// ── st:MultiStepExecution — work accumulation over N atomic steps ─────

/// Number of words in the step plane (tier-typed stand-in for Work<BITS>).
pub const MULTI_STEP_WORDS: usize = 4;

/// Word-plane step machine: each step is globally atomic across the active
/// word set — every active word's gate must pass or NO word mutates
/// (unibit execute_step_multi deny_acc lib.rs:1004-1012); admitted steps
/// accumulate work monotonically.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MultiStepWork {
    plane: [u64; MULTI_STEP_WORDS],
    work: u64,
}

impl MultiStepWork {
    pub const fn new() -> MultiStepWork {
        MultiStepWork { plane: [0u64; MULTI_STEP_WORDS], work: 0 }
    }

    pub fn plane(&self) -> [u64; MULTI_STEP_WORDS] {
        self.plane
    }

    /// Work accumulated by admitted steps only; monotone non-decreasing.
    pub fn work(&self) -> u64 {
        self.work
    }

    /// One atomic step: `gates` names, per plane word, the bits that must be
    /// SET for the step to admit; `writes` names the bits to set on
    /// admission. All gates are evaluated BEFORE any word is written; any
    /// failure suppresses the whole step (all-or-nothing) and returns false
    /// without touching the plane or the work counter.
    pub fn execute_step(&mut self, gates: &[u64], writes: &[u64]) -> bool {
        assert!(gates.len() == MULTI_STEP_WORDS && writes.len() == MULTI_STEP_WORDS);
        // Phase 1 — accumulate denial across ALL words before any write.
        let mut deny_acc: u64 = 0;
        let mut k = 0usize;
        while k < MULTI_STEP_WORDS {
            deny_acc |= gates[k] & !self.plane[k];
            k += 1;
        }
        if deny_acc != 0 {
            return false;
        }
        // Phase 2 — commit (reached only when every gate passed).
        let mut k = 0usize;
        while k < MULTI_STEP_WORDS {
            self.plane[k] |= writes[k];
            k += 1;
        }
        self.work = self.work + 1;
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── st:SparseDelta courts ──────────────────────────────────────────

    #[test]
    fn sparse_delta_no_op_on_empty() {
        let block = [0x1111u64, 0x2222, 0x3333, 0x4444];
        let before = block;
        let mut b2 = block;
        sparse_delta_apply(&mut b2, &SparseDelta::empty());
        assert_eq!(b2, before, "empty delta must be a no-op (all-or-nothing)");
    }

    #[test]
    fn sparse_delta_total_on_apply_round_trip() {
        let before = [0xDEAD_BEEFu64, 0, 0xCAFE_BABE, 7];
        let after = [0xDEAD_BEEFu64, 1, 0xCAFE_BABE, 0xFFFF_0000_0000_0001];
        let d = sparse_delta_emit(&before, &after);
        assert_eq!(d.count, 2, "only changed words recorded");
        let mut b = before;
        sparse_delta_apply(&mut b, &d);
        assert_eq!(b, after, "round-trip forward");
        sparse_delta_apply(&mut b, &d);
        assert_eq!(b, before, "apply twice = XOR self-inverse identity");
    }

    #[test]
    fn sparse_delta_emits_only_changed_words() {
        let before = [0u64; 8];
        let mut after = [0u64; 8];
        after[0] = 1;
        after[7] = u64::MAX;
        let d = sparse_delta_emit(&before, &after);
        assert_eq!(d.count, 2);
        assert_eq!(d.indices[0], 0);
        assert_eq!(d.words[1], u64::MAX);
    }

    #[test]
    fn all_or_nothing_court_catches_sabotage() {
        // The court: on an EMPTY delta the block must be untouched.
        let before = [0xAAAAu64, 0xBBBB, 0xCCCC, 0xDDDD];
        let empty = SparseDelta::empty();
        // Honest apply passes the court.
        let mut honest = before;
        sparse_delta_apply(&mut honest, &empty);
        assert_eq!(honest, before, "honest apply: empty delta is a no-op");
        // Sabotage twin (mutates in place BEFORE checking the mask) must
        // fail the same court: it clobbers words via the stale zero slots.
        let mut sabotaged = before;
        sabotage_delta_apply(&mut sabotaged, &empty);
        assert_ne!(
            sabotaged, before,
            "sabotage twin must violate the all-or-nothing court"
        );
        // And on a 1-word delta the sabotage also corrupts the other words.
        let mut after = before;
        after[2] ^= 0xFF;
        let d = sparse_delta_emit(&before, &after);
        let mut sabotaged2 = before;
        sabotage_delta_apply(&mut sabotaged2, &d);
        assert_ne!(sabotaged2, after, "sabotage writes outside the mask");
        let mut honest2 = before;
        sparse_delta_apply(&mut honest2, &d);
        assert_eq!(honest2, after);
    }

    // ── st:BitfenwickSum courts ────────────────────────────────────────

    #[test]
    fn bitfenwick_matches_reference_over_200_cases() {
        // 200 deterministic (lane, delta) cases vs the naive prefix-sum
        // reference; every prefix checked after every add.
        let mut seed: u64 = 0x243F6A8885A308D3;
        let mut subject = Bitfenwick8::zero();
        let mut reference = NaivePrefix::zero();
        let mut n = 0usize;
        while n < 200 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let idx = ((seed >> 33) % (BITFENWICK_LANES as u64)) as u32 + 1;
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let delta = (seed >> 16) as u32;
            subject.add(idx, delta);
            reference.add(idx, delta);
            // After every add, every prefix must match the reference.
            let mut p = 1u32;
            while p <= BITFENWICK_LANES as u32 {
                assert_eq!(
                    subject.sum_prefix(p),
                    reference.sum_prefix(p),
                    "prefix {} diverges after case {}",
                    p,
                    n
                );
                p += 1;
            }
            n += 1;
        }
        // Note: tree lanes legitimately differ from the naive value array
        // (Fenwick nodes store range sums); the semantic property is that
        // EVERY prefix sum matched after EVERY add.
    }

    #[test]
    fn bitfenwick_carry_stays_in_lane() {
        // Near-overflow deltas: every add wraps inside one u32 lane
        // (wrapping_add), so the u32 arithmetic carry never borrows across
        // positions — proven by exact prefix agreement with the naive
        // wrapping reference at EVERY boundary, and by prefixes strictly
        // below the touched position staying at zero.
        let mut subject = Bitfenwick8::zero();
        let mut reference = NaivePrefix::zero();
        let mut n = 0usize;
        while n < 200 {
            subject.add(3, 0xFFFF_FFFFu32);
            reference.add(3, 0xFFFF_FFFFu32);
            assert_eq!(subject.sum_prefix(2), 0, "prefix below the lane is untouched");
            let mut p = 1u32;
            while p <= BITFENWICK_LANES as u32 {
                assert_eq!(
                    subject.sum_prefix(p),
                    reference.sum_prefix(p),
                    "prefix {} diverges at wrap case {}",
                    p,
                    n
                );
                p += 1;
            }
            n += 1;
        }
    }

    // ── st:MultiStepExecution courts ───────────────────────────────────

    #[test]
    fn multi_step_work_accumulates_monotonically_over_200() {
        let mut w = MultiStepWork::new();
        let mut seed: u64 = 0x13198A2E03707344;
        // Seed the plane once (empty-gate step) so later gates can pass.
        assert!(w.execute_step(&[0, 0, 0, 0], &[1, 0, 0, 0]));
        let mut last_work: u64 = w.work();
        let mut admitted: u64 = 1;
        let mut n = 0usize;
        while n < 200 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let gate_bit = 1u64 << ((seed >> 40) % 64);
            let gate = [gate_bit, 0, 0, 0];
            let write = [1u64 << (n % 64), 0, 0, 0];
            let ok = w.execute_step(&gate, &write);
            if ok {
                admitted += 1;
            }
            assert!(
                w.work() >= last_work,
                "work must be monotone non-decreasing (step {})",
                n
            );
            assert_eq!(w.work(), admitted, "work counts admitted steps only");
            last_work = w.work();
            n += 1;
        }
        assert!(admitted >= 1, "deterministic sequence must admit some steps");
        assert_eq!(w.work(), admitted);
    }

    #[test]
    fn multi_step_denied_step_mutates_nothing() {
        let mut w = MultiStepWork::new();
        // Step 1: admitted — empty gates, write bit 0 of word 0.
        assert!(w.execute_step(&[0, 0, 0, 0], &[1, 0, 0, 0]));
        let (plane_before, work_before) = (w.plane(), w.work());
        // Step 2: word 1's gate fails (bit 1 absent) — whole step refuses.
        assert!(!w.execute_step(&[0, 2, 0, 0], &[4, 8, 0, 0]));
        assert_eq!(w.plane(), plane_before, "denied step must not touch the plane");
        assert_eq!(w.work(), work_before, "denied step must not accrue work");
        // Partial-supply witness: one satisfied word gate is NOT enough —
        // global atomicity suppresses the satisfied word too.
        assert!(!w.execute_step(&[0, 2, 0, 0], &[1, 0, 0, 0]));
        assert_eq!(w.plane(), plane_before);
        assert_eq!(w.work(), work_before);
    }
}
